// Fatura ve teklif taslağının saf mantığı: kuruş tamsayısıyla hesap, giriş yazımı, doğrulama ve yazımlar.
// Para hesabı kayan noktayla değil ABACUS'un `math` ve `money.toMinor` araçlarıyla (alt birim tamsayısı) yapılır.
// Ekrandaki toplam yalnızca gösterimdir: gerçek belgede toplam sunucuda yeniden hesaplanır.
import { math, money } from "@snn/abacus-core";
import { formatMoney, formatNumber, formatPercent } from "../lib/chart-format";

export interface InvoiceItem {
  id: string;
  description: string;
  /** Ondalık olabilir (örneğin 2,5). */
  quantity: number;
  /** Birim fiyat, ana birimde TRY (örneğin 1250.5). */
  unitPrice: number;
}

export interface Totals {
  /** Satır tutarları (kuruş tamsayısı), kalem sırasıyla. */
  lines: number[];
  subtotalMinor: number;
  vatMinor: number;
  totalMinor: number;
}

/** Satır tutarı: adet × birim fiyat, kuruşa yuvarlanmış tamsayı. Geçersizse 0. */
export function lineMinor(item: Pick<InvoiceItem, "quantity" | "unitPrice">): number {
  const amount = math.mul(Math.max(item.quantity, 0), Math.max(item.unitPrice, 0));
  return money.toMinor(amount) ?? 0;
}

/** Toplamlar: her satır kuruşa yuvarlanır, KDV ara toplam üzerinden bir kez hesaplanıp kuruşa yuvarlanır. */
export function computeTotals(items: Pick<InvoiceItem, "quantity" | "unitPrice">[], vatRate: number): Totals {
  const lines = items.map(lineMinor);
  const subtotalMinor = lines.reduce((sum, minor) => math.add(sum, minor), 0);
  const vatMinor = math.round(math.mul(subtotalMinor, vatRate / 100), 0);
  return { lines, subtotalMinor, vatMinor, totalMinor: math.add(subtotalMinor, vatMinor) };
}

/** Kuruş tamsayısı → ana birim ("123450" → 1234.5), yalnız gösterim için. */
export const majorOf = (minor: number) => math.div(minor, 100) ?? 0;
/** Kuruş tamsayısını TRY olarak yazar: "₺1.234,50". */
export const minorText = (minor: number) => formatMoney(majorOf(minor), 2);

/** Alanda yazılan metni Türkçe ayraçla biçimler: "1250,5" → "1.250,5" (en çok `digits` ondalık). */
export const groupedInput = (raw: string, digits = 2) => money.formatGroupedInput(raw, { maxDigits: digits });
/** Alandaki metni sayıya çevirir; boş ya da geçersizse null. */
export function parseField(text: string): number | null {
  const trimmed = text.trim();
  return trimmed ? money.parseNumber(trimmed) : null;
}
/** Sayıyı alan metnine çevirir (1250.5 → "1.250,5"); sondaki sıfırlar atılır. */
export function fieldText(value: number, digits = 2): string {
  const text = money.fmtDecimalGrouped(value, digits);
  return text.includes(",") ? text.replace(/0+$/, "").replace(/,$/, "") : text;
}

export const quantityText = (quantity: number) => money.decimal(quantity, 3);
export const vatLabel = (rate: number) => `KDV · ${formatPercent(rate, 0)}`;
export const countText = (count: number) => formatNumber(count, 0);

export interface ItemProblem { id: string; message: string }
/** Kayıt öncesi doğrulama: açıklaması boş kalem. */
export function validateItems(items: Pick<InvoiceItem, "id" | "description">[]): ItemProblem[] {
  return items.filter(item => !item.description.trim()).map(item => ({ id: item.id, message: "Her kalem için açıklama girin" }));
}

.root { container-type: inline-size; display: grid; min-width: 0; gap: var(--space-5); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); }
.top { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: var(--space-5); }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-4xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); }
.parties { display: flex; flex-wrap: wrap; gap: var(--space-6); font-size: var(--text-sm); }
.parties > div { display: grid; gap: 2px; min-width: 9rem; }
.partyLabel { color: var(--text-muted); font-size: var(--text-xs); }
.table { display: grid; min-width: 0; }
.head, .rowInner { display: grid; grid-template-columns: minmax(0, 1fr) 6rem 9rem 9rem 2rem; align-items: center; gap: var(--space-3); }
.head { padding: 0 0 var(--space-2); border-bottom: 1px solid var(--border); color: var(--text-secondary); font-size: var(--text-xs); }
.head span:nth-child(n+2):not(:last-child) { text-align: right; }
.row { border-bottom: 1px solid var(--border-subtle); }
.rowInner { padding: var(--space-2) 0; }
.cell { display: grid; gap: var(--space-1); }
.cellLabel { display: none; color: var(--text-muted); font-size: var(--text-xs); }
.cell input, .note textarea { width: 100%; min-width: 0; box-sizing: border-box; min-height: var(--control-height-sm); padding: 0 var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font: inherit; font-size: var(--text-sm); }
.cell[data-cell="quantity"] input, .money input { text-align: right; font-variant-numeric: tabular-nums; }
.cell input:focus-visible, .note textarea:focus-visible, .remove:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.cell input[aria-invalid="true"] { border-color: var(--danger); }
.money { position: relative; display: block; }
.money i { position: absolute; top: 50%; left: var(--space-3); transform: translateY(-50%); color: var(--text-muted); font-style: normal; font-size: var(--text-sm); }
.money input { width: 100%; padding-left: var(--space-6); }
.amount { text-align: right; font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.remove { width: 2rem; height: 2rem; border: 0; border-radius: var(--radius-control); background: transparent; color: var(--text-muted); font-size: var(--text-sm); cursor: pointer; }
.remove:hover { background: var(--surface-muted); color: var(--foreground); }
.rowError { margin: 0 0 var(--space-2); color: var(--danger); font-size: var(--text-xs); }
.empty { margin: 0; padding: var(--space-6) 0; color: var(--text-muted); text-align: center; font-size: var(--text-sm); }
.lower { display: grid; grid-template-columns: minmax(0, 1fr) minmax(14rem, 20rem); gap: var(--space-6); align-items: start; }
.note { display: grid; gap: var(--space-1); color: var(--text-secondary); font-size: var(--text-xs); }
.note textarea { padding: var(--space-3); resize: vertical; }
.totals { display: grid; gap: var(--space-2); font-size: var(--text-sm); }
.totalRow, .grand { display: flex; justify-content: space-between; align-items: baseline; gap: var(--space-3); font-variant-numeric: tabular-nums; }
.totalRow span { color: var(--text-secondary); }
.grand { padding-top: var(--space-3); border-top: 1px solid var(--border-strong); }
.grand b { font-family: var(--font-display); font-size: var(--text-2xl); letter-spacing: var(--tracking-display); font-weight: 500; }
.footer { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--space-4); }
.status { margin: 0; margin-right: auto; font-size: var(--text-sm); color: var(--text-secondary); }
.status[data-tone="error"] { color: var(--danger); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@container (max-width: 760px) { .head, .rowInner { grid-template-columns: minmax(0, 1fr) 5rem 7.5rem 7.5rem 2rem; gap: var(--space-2); } .lower { grid-template-columns: minmax(0, 1fr); } }
@container (max-width: 620px) {
  .root { padding: var(--space-4); }
  .head { display: none; }
  .rowInner { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) 2rem; grid-template-areas: "description description remove" "quantity price price" "amount amount amount"; padding: var(--space-3) 0; }
  .cell[data-cell="description"] { grid-area: description; }
  .cell[data-cell="quantity"] { grid-area: quantity; }
  .cell[data-cell="price"] { grid-area: price; }
  .amount { grid-area: amount; display: flex; justify-content: space-between; }
  .remove { grid-area: remove; align-self: start; }
  .cellLabel { display: block; }
}
@container (max-width: 380px) { .parties { display: grid; gap: var(--space-3); } }

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Button } from "../button/button";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { computeTotals, fieldText, groupedInput, majorOf, minorText, parseField, validateItems, vatLabel, type InvoiceItem } from "./invoice-studio-format";
import styles from "./invoice-studio.module.css";

export type { InvoiceItem };
export interface InvoiceParty { name: string; lines?: string[] }
export interface InvoiceDraft { kind: "invoice" | "quote"; items: InvoiceItem[]; vatRate: number; note: string }

/** Kalemli bir fatura ya da teklif taslağını ekranda düzenletmek için kullanın (kalem ekle ve sil, adet ve birim fiyat değiştikçe ara toplam, KDV ve genel toplam anında hesaplanır). Yalnız taslağı düzenler; resmî e-fatura ya da e-arşiv üretimi ve gönderimi kapsam dışıdır, toplam gerçek belgede sunucuda yeniden hesaplanmalıdır. */
export interface InvoiceStudioProps {
  kind?: "invoice" | "quote";
  sender: InvoiceParty;
  recipient: InvoiceParty;
  /** Başlangıç kalemleri; sonra bileşen tutar. */
  defaultItems?: InvoiceItem[];
  /** KDV oranı (yüzde); proje ayarından gelir. */
  vatRate?: number;
  defaultNote?: string;
  /** Taslağı kaydeder; reddederse (Promise) "Kaydedilemedi" yazılır ve yeniden denenebilir. */
  onSave: (draft: InvoiceDraft) => Promise<void>;
  /** Her değişiklikte çağrılır (taslağı dışarıda izlemek için). */
  onChange?: (draft: InvoiceDraft) => void;
}

interface Row { id: string; description: string; quantityText: string; priceText: string }
const toRow = (item: InvoiceItem): Row => ({ id: item.id, description: item.description, quantityText: fieldText(item.quantity, 3), priceText: fieldText(item.unitPrice, 2) });

export function InvoiceStudio({ kind = "invoice", sender, recipient, defaultItems = [], vatRate = 20, defaultNote = "", onSave, onChange }: InvoiceStudioProps) {
  const reduced = useReducedMotionSafe();
  const baseId = useId();
  const [rows, setRows] = useState<Row[]>(() => defaultItems.map(toRow));
  const [note, setNote] = useState(defaultNote);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ tone: "ok" | "error"; text: string } | null>(null);
  const [flagged, setFlagged] = useState<string[]>([]);
  const nextId = useRef(defaultItems.length + 1);
  const focusId = useRef<string | null>(null);

  const items: InvoiceItem[] = useMemo(() => rows.map(row => ({ id: row.id, description: row.description, quantity: Math.max(parseField(row.quantityText) ?? 0, 0), unitPrice: Math.max(parseField(row.priceText) ?? 0, 0) })), [rows]);
  const totals = useMemo(() => computeTotals(items, vatRate), [items, vatRate]);
  const title = kind === "invoice" ? "Fatura" : "Teklif";

  useEffect(() => { onChange?.({ kind, items, vatRate, note }); }, [items, note, kind, vatRate]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (!focusId.current) return;
    const node = document.getElementById(`${baseId}-${focusId.current}-description`);
    focusId.current = null;
    node?.focus();
  }, [rows, baseId]);

  const update = (id: string, patch: Partial<Row>) => { setRows(current => current.map(row => row.id === id ? { ...row, ...patch } : row)); setFlagged(current => current.filter(item => item !== id)); setMessage(null); };
  const add = () => { const id = `kalem-${nextId.current++}`; focusId.current = id; setRows(current => [...current, { id, description: "", quantityText: "1", priceText: "" }]); setMessage(null); };
  const remove = (id: string) => { setRows(current => current.filter(row => row.id !== id)); setFlagged(current => current.filter(item => item !== id)); };

  const save = async () => {
    const problems = validateItems(items);
    if (problems.length) { setFlagged(problems.map(problem => problem.id)); setMessage({ tone: "error", text: problems[0]!.message }); return; }
    setSaving(true); setMessage(null);
    try { await onSave({ kind, items, vatRate, note }); setMessage({ tone: "ok", text: "Taslak kaydedildi" }); }
    catch { setMessage({ tone: "error", text: "Kaydedilemedi" }); }
    finally { setSaving(false); }
  };

  const spring = reduced ? { duration: 0 } : { duration: .24, ease: [.22, 1, .36, 1] as [number, number, number, number] };

  return <section className={styles.root} data-reduced={reduced || undefined} aria-label={`${title} taslağı`}>
    <header className={styles.top}>
      <h3 className={styles.title}>{title}</h3>
      <div className={styles.parties}>
        <div><span className={styles.partyLabel}>Gönderen</span><b>{sender.name}</b>{sender.lines?.map(line => <span key={line}>{line}</span>)}</div>
        <div><span className={styles.partyLabel}>Alıcı</span><b>{recipient.name}</b>{recipient.lines?.map(line => <span key={line}>{line}</span>)}</div>
      </div>
    </header>

    <div className={styles.table} role="table" aria-label="Kalemler">
      <div className={styles.head} role="row"><span role="columnheader">İş / hizmet</span><span role="columnheader">Adet</span><span role="columnheader">Birim fiyat</span><span role="columnheader">Tutar</span><span role="columnheader" className={styles.srOnly}>Sil</span></div>
      {rows.length === 0 && <p className={styles.empty}>Henüz kalem yok.</p>}
      <AnimatePresence initial={false}>
        {rows.map((row, at) => {
          const flag = flagged.includes(row.id);
          return <motion.div key={row.id} role="row" className={styles.row} data-flag={flag || undefined} initial={reduced ? false : { height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={spring} style={{ overflow: "hidden" }}>
            <div className={styles.rowInner}>
              <label className={styles.cell} data-cell="description"><span className={styles.cellLabel}>İş / hizmet</span>
                <input id={`${baseId}-${row.id}-description`} value={row.description} onChange={event => update(row.id, { description: event.target.value })} aria-label={`${at + 1}. kalem açıklama`} aria-invalid={flag || undefined} aria-describedby={flag ? `${baseId}-${row.id}-error` : undefined} /></label>
              <label className={styles.cell} data-cell="quantity"><span className={styles.cellLabel}>Adet</span>
                <input inputMode="decimal" autoComplete="off" value={row.quantityText} onChange={event => update(row.id, { quantityText: groupedInput(event.target.value, 3) })} onBlur={() => update(row.id, { quantityText: fieldText(Math.max(parseField(row.quantityText) ?? 0, 0), 3) })} aria-label={`${at + 1}. kalem adet`} /></label>
              <label className={styles.cell} data-cell="price"><span className={styles.cellLabel}>Birim fiyat</span>
                <span className={styles.money}><i aria-hidden="true">₺</i><input inputMode="decimal" autoComplete="off" value={row.priceText} onChange={event => update(row.id, { priceText: groupedInput(event.target.value, 2) })} aria-label={`${at + 1}. kalem birim fiyat`} /></span></label>
              <span className={styles.amount}><span className={styles.cellLabel}>Tutar</span><span className={styles.srOnly}>{`${at + 1}. kalem tutar `}</span>{minorText(totals.lines[at] ?? 0)}</span>
              <button type="button" className={styles.remove} onClick={() => remove(row.id)} aria-label={`${at + 1}. kalemi sil`}>✕</button>
            </div>
            {flag && <p id={`${baseId}-${row.id}-error`} className={styles.rowError}>Her kalem için açıklama girin</p>}
          </motion.div>;
        })}
      </AnimatePresence>
    </div>
    <div><Button size="sm" variant="secondary" onClick={add}>+ Kalem ekle</Button></div>

    <div className={styles.lower}>
      <label className={styles.note}><span>Not</span><textarea rows={3} value={note} onChange={event => setNote(event.target.value)} placeholder="Ödeme koşulu gibi kısa bir not" /></label>
      <output className={styles.totals} aria-live="polite" aria-atomic="true">
        <span className={styles.srOnly}>{`Ara toplam ${minorText(totals.subtotalMinor)}, ${vatLabel(vatRate)} ${minorText(totals.vatMinor)}, ödenecek toplam ${minorText(totals.totalMinor)}`}</span>
        <span className={styles.totalRow} aria-hidden="true"><span>Ara toplam</span><b><AnimatedCounter value={majorOf(totals.subtotalMinor)} decimals={2} prefix="₺" /></b></span>
        <span className={styles.totalRow} aria-hidden="true"><span>{vatLabel(vatRate)}</span><b><AnimatedCounter value={majorOf(totals.vatMinor)} decimals={2} prefix="₺" /></b></span>
        <span className={styles.grand} aria-hidden="true"><span>Ödenecek toplam</span><b><AnimatedCounter value={majorOf(totals.totalMinor)} decimals={2} prefix="₺" /></b></span>
      </output>
    </div>

    <footer className={styles.footer}>
      <p className={styles.status} role="status" aria-live="polite" data-tone={message?.tone}>{saving ? "Kaydediliyor…" : message?.text ?? ""}</p>
      <Button variant="primary" onClick={save} disabled={saving} loading={saving}>Taslağı kaydet</Button>
    </footer>
  </section>;
}

export default InvoiceStudio;
